  A.rowToEvent = (r, src = 'bundled') => {
    const [when, dur, sport, comp, detail, ch, status] = r;
    const start = new Date(when.replace(' ', 'T') + ':00Z');
    const m = / v(?:s\.?)? /i.exec(detail);
    const ev = {
      id: A.slug(`${when}-${comp}-${detail}`), sport, comp, detail,
      start: start.toISOString(), end: new Date(+start + dur * 60000).toISOString(),
      channels: ch.split(/\s+/).filter(Boolean), status: status || 'L', src
    };
    if (m) { ev.home = detail.slice(0, m.index).trim(); ev.away = detail.slice(m.index + m[0].length).trim(); }
    return ev;
  };
  A.SEED = rows.map((r) => A.rowToEvent(r));
